### How do the three constraint sets work?

For O(1) conflict detection, maintain three `HashSet<Integer>` values:
- `cols`: which columns are occupied.
- `diag1`: which `row - col` values are occupied (down-right diagonal).
- `diag2`: which `row + col` values are occupied (down-left diagonal).

Cells on the same down-right diagonal share the same `row - col` value. Cells on the same down-left diagonal share the same `row + col` value. A cell at (r, c) is safe exactly when `cols`, `diag1`, and `diag2` do not contain c, r-c, and r+c respectively.

```java
package com.bank.service;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class NQueens {
    private int count = 0;

    public List<List<String>> solveNQueens(int n) {
        List<List<String>> solutions = new ArrayList<>();
        Set<Integer> cols = new HashSet<>();
        Set<Integer> diag1 = new HashSet<>(); // row - col
        Set<Integer> diag2 = new HashSet<>(); // row + col
        int[] queens = new int[n]; // queens[row] = col

        backtrack(n, 0, queens, cols, diag1, diag2, solutions);
        return solutions;
    }

    private void backtrack(int n, int row, int[] queens,
                           Set<Integer> cols, Set<Integer> diag1,
                           Set<Integer> diag2,
                           List<List<String>> solutions) {
        if (row == n) {
            solutions.add(buildBoard(queens, n));
            count++;
            return;
        }
        for (int col = 0; col < n; col++) {
            if (cols.contains(col) || diag1.contains(row - col)
                || diag2.contains(row + col)) {
                continue; // conflict
            }
            queens[row] = col;
            cols.add(col);
            diag1.add(row - col);
            diag2.add(row + col);

            backtrack(n, row + 1, queens, cols, diag1, diag2, solutions);

            cols.remove(col);
            diag1.remove(row - col);
            diag2.remove(row + col);
        }
    }

    private List<String> buildBoard(int[] queens, int n) {
        List<String> board = new ArrayList<>();
        for (int row = 0; row < n; row++) {
            char[] line = new char[n];
            java.util.Arrays.fill(line, '.');
            line[queens[row]] = 'Q';
            board.add(new String(line));
        }
        return board;
    }

    public static void main(String[] args) {
        NQueens solver = new NQueens();
        List<List<String>> solutions = solver.solveNQueens(4);
        System.out.println("4-Queens solutions: " + solutions.size());
        for (List<String> sol : solutions) {
            sol.forEach(System.out::println);
            System.out.println();
        }
    }
}
```

